    ) {
        if (cpf != null) {
            return new IndividualGuest(cpf);
        }

        if (cnpj != null) {
            return new CorporateGuest(cnpj, companyName);
        }

        if (passport != null) {
            return new ForeignGuest(passport, country);
        }

        throw new IllegalStateException("Invalid guest type data");
    }
}

